-- Solo bases VACÍAS. En bases existentes de la etapa 2 ejecutar únicamente 002.
CREATE TABLE usuarios (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, email VARCHAR(150) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, rol ENUM('ALUMNO','PROFESOR','ADMIN') NOT NULL) ENGINE=InnoDB;
CREATE TABLE profesores (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(20) NOT NULL, apellido VARCHAR(20) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, especialidad VARCHAR(100) NOT NULL, usuario_id BIGINT UNIQUE, FOREIGN KEY (usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE alumnos (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(20) NOT NULL, apellido VARCHAR(20) NOT NULL, edad INT NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, fecha_nacimiento DATE, nivel ENUM('PRINCIPIANTE','INTERMEDIO','AVANZADO'), objetivo ENUM('PERDER_PESO','GANAR_MASA_MUSCULAR','MEJORAR_RESISTENCIA'), usuario_id BIGINT UNIQUE, FOREIGN KEY (usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE alumnos_profesore (alumno_id BIGINT NOT NULL, profesor_id BIGINT NOT NULL, FOREIGN KEY (alumno_id) REFERENCES alumnos(id), FOREIGN KEY (profesor_id) REFERENCES profesores(id)) ENGINE=InnoDB;
CREATE TABLE rutinas (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(255) NOT NULL, descripcion VARCHAR(255) NOT NULL, profesor_id BIGINT, FOREIGN KEY (profesor_id) REFERENCES profesores(id)) ENGINE=InnoDB;
CREATE TABLE ejercicios (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(60) NOT NULL, descripcion VARCHAR(255) NOT NULL, grupo_muscular ENUM('PECHO','ESPALDA','PIERNAS','BRAZOS','HOMBROS','ABDOMINALES')) ENGINE=InnoDB;
CREATE TABLE dias_rutina (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(255) NOT NULL, numero_orden INT NOT NULL, rutina_id BIGINT, FOREIGN KEY (rutina_id) REFERENCES rutinas(id)) ENGINE=InnoDB;
CREATE TABLE dias_ejercicio (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, dia_rutina_id BIGINT, ejercicio_id BIGINT, series_sugeridas INT NOT NULL, reps_sugeridas INT NOT NULL, peso_sugerido DOUBLE, FOREIGN KEY (dia_rutina_id) REFERENCES dias_rutina(id), FOREIGN KEY (ejercicio_id) REFERENCES ejercicios(id)) ENGINE=InnoDB;
CREATE TABLE asignaciones_rutina (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, alumno_id BIGINT, rutina_id BIGINT, fecha_inicio DATETIME(6), fecha_fin DATETIME(6), activa BIT(1) NOT NULL, FOREIGN KEY (alumno_id) REFERENCES alumnos(id), FOREIGN KEY (rutina_id) REFERENCES rutinas(id)) ENGINE=InnoDB;
CREATE TABLE sesiones (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, alumno_id BIGINT, dia_rutina_id BIGINT, fecha DATE NOT NULL, completada BIT(1) NOT NULL, FOREIGN KEY (alumno_id) REFERENCES alumnos(id), FOREIGN KEY (dia_rutina_id) REFERENCES dias_rutina(id)) ENGINE=InnoDB;
CREATE TABLE series (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, sesion_id BIGINT, dia_ejercicio_id BIGINT, numero_serie INT NOT NULL, reps_hechas INT, peso_usado DOUBLE, completada BIT(1) NOT NULL, FOREIGN KEY (sesion_id) REFERENCES sesiones(id), FOREIGN KEY (dia_ejercicio_id) REFERENCES dias_ejercicio(id)) ENGINE=InnoDB;
